package com.careerguidance.controller;
import com.careerguidance.dto.request.RejectionRequest; import com.careerguidance.dto.response.*; import com.careerguidance.service.MentorVerificationService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/mentors") @PreAuthorize("hasRole('ADMIN')") public class AdminMentorVerificationController { private final MentorVerificationService service; public AdminMentorVerificationController(MentorVerificationService s){service=s;} @GetMapping("/pending") public List<MentorProfileResponse> pending(){return service.pending();} @GetMapping("/{id}") public MentorProfileResponse detail(@PathVariable Long id){return service.detail(id);} @PostMapping("/{id}/approve") public MessageResponse approve(@PathVariable Long id,Authentication a){return service.approve(id,a.getName());} @PostMapping("/{id}/reject") public MessageResponse reject(@PathVariable Long id,@Valid @RequestBody RejectionRequest r,Authentication a){return service.reject(id,r,a.getName());} @GetMapping("/statistics") public Map<String,Long> stats(){return service.statistics();} }
